-- 256418: enable quest-giver interaction only for the exact imported starter and unchanged placeholder flags.
UPDATE `creature_template` c
SET c.`npcflag` = c.`npcflag` | 2 WHERE c.`entry` = 256418 AND c.`npcflag` = 0 AND c.`VerifiedBuild` = 0
AND EXISTS (SELECT 1 FROM `creature_queststarter` s WHERE s.`id` = c.`entry` AND s.`quest` = 93786 AND s.`VerifiedBuild` = 0)
AND EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl` = 'creature_queststarter' AND r.`k1` = c.`entry` AND r.`k2` = 93786 AND r.`file` = '2026_11_10_00_world_everlake_import_slice6.sql');

